import unittest
from candidate import below_zero

class TestBelowZero(unittest.TestCase):
    def test_below_zero_positive_operations(self):
        self.assertFalse(below_zero([1, 2, 3]))

    def test_below_zero_mixed_operations(self):
        self.assertTrue(below_zero([1, 2, -4, 5]))

    def test_below_zero_only_withdrawal(self):
        self.assertTrue(below_zero([-1, -2, -3]))

    def test_below_zero_only_deposit(self):
        self.assertFalse(below_zero([1, 2, 3, 4, 5]))

    def test_below_zero_empty_operations(self):
        self.assertFalse(below_zero([]))

    def test_below_zero_single_operation(self):
        self.assertTrue(below_zero([-1]))

    def test_below_zero_single_operation_positive(self):
        self.assertFalse(below_zero([1]))

    def test_below_zero_operations_with_zero(self):
        self.assertFalse(below_zero([1, 0, 2, 0, 3]))

    def test_below_zero_operations_with_zero_becomes_negative(self):
        self.assertTrue(below_zero([1, 0, -2, 0, -3]))

    def test_below_zero_none_input(self):
        with self.assertRaises(TypeError):
            below_zero(None)

    def test_below_zero_non_list_input(self):
        with self.assertRaises(TypeError):
            below_zero("not a list")

    def test_below_zero_list_with_non_numeric_values(self):
        with self.assertRaises(TypeError):
            below_zero([1, "2", 3])

if __name__ == '__main__':
    unittest.main()
